method total_match(lst1: seq<string>, lst2: seq<string>) returns (result: seq<string>)
    requires |lst1| >= 0 && |lst2| >= 0 // Both lists can be empty
    ensures (|lst1| == 0 && |lst2| == 0) ==> result == []
    ensures (|lst1| > 0 || |lst2| > 0) ==> 
        (|lst1| > 0 && |lst2| > 0 && 
         total_char_count(lst1) < total_char_count(lst2) ==> result == lst1 ||
         total_char_count(lst1) > total_char_count(lst2) ==> result == lst2 ||
         total_char_count(lst1) == total_char_count(lst2) ==> result == lst1)
    ensures |result| >= 0 // The result is always a valid sequence

method total_char_count(lst: seq<string>) returns (count: int)
    ensures count >= 0 // The count of characters is non-negative
{
    count := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst| // i is within bounds
        invariant count == sum_length(lst, i) // count is the sum of lengths of strings up to index i
    {
        count := count + |lst[i]|;
        i := i + 1;
    }
}

function sum_length(lst: seq<string>, n: int): int
    requires 0 <= n <= |lst|
    reads lst
{
    if n == 0 then
        0
    else
        |lst[n - 1]| + sum_length(lst, n - 1)
}
